mapper.select:


    inner join sys_user u on u.user_name = toutdelivery.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    toutdelivery.del_flag = '0'
     and toutdelivery.code like concat('%', #{code}, '%')
     and toutdelivery.origin_code like concat('%', #{originCode}, '%')
     and toutdelivery.origin_date = #{originDate}
     and toutdelivery.origin_data = #{originData}
     and toutdelivery.complete_state = #{completeState}
     and toutdelivery.type = #{type}
     and toutdelivery.status = #{status}
     and toutdelivery.auditor = #{auditor}
     and toutdelivery.new_local = #{newLocal}
    and toutdelivery.delivery_module = #{deliveryModule}
     and toutdelivery.reflux_status = #{refluxStatus}


${params.dataScope}
order by toutdelivery.create_time desc

SELECT a.id, a.`name`, a.`code`, a.unit_id, c.`name` unit_name, d.count,( SELECT NAME FROM t_unit WHERE id = d.min_unit_id ) min_unit_name ,a.stock FROM (SELECT a.id ,a.`name`,a.`code`,a.unit_id,sum(b.available_count) stock from t_material a join t_stock b on a.id = b.material_id AND b.`status` = 0 AND b.available_count > 0 AND b.is_freeze = 0
AND b.location_id in
#{item}
AND b.del_flag = 0 GROUP BY a.id) a LEFT JOIN t_unit c ON a.unit_id = c.id LEFT JOIN t_unit_config d ON a.id = d.material_id 1=1 and a.code like "%" #{code} "%" and a.`name` like "%" #{name} "%"
${params.dataScope}



    inner join sys_user u on u.user_name = toutdelivery.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'

    left join t_out_delivery_detail toutdetail on toutdelivery.id = toutdetail.out_delivery_id

    toutdelivery.del_flag = '0'
        and toutdetail.small_predict_count is null
        and toutdelivery.status = 2
        and toutdelivery.complete_state = 1
     and toutdelivery.code like concat('%', #{code}, '%')
     and toutdelivery.origin_code like concat('%', #{originCode}, '%')
     and toutdelivery.origin_date = #{originDate}
     and toutdelivery.origin_data = #{originData}
     and toutdelivery.complete_state = #{completeState}
     and toutdelivery.type = #{type}
     and toutdelivery.status = #{status}
     and toutdelivery.auditor = #{auditor}
     and toutdelivery.new_local = #{newLocal}


${params.dataScope}
order by toutdelivery.create_time desc
